#!/usr/bin/env bash
# The terminal sessions quoted in lesson 25 of gcp-operations.
#
#   bash captures.sh     # after lab.sh student; needs nothing but Python
#
# The daily costs are generated by days.py, as the lesson says; no billing
# export or budget was read.

HERE=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=../../capture.sh
. "$HERE/../../capture.sh"
mkdir -p "$HOME/gcp/bill" && cd "$HOME/gcp/bill" || exit 1
from_lesson "$HERE/spikes.md" days.py > days.py
from_lesson "$HERE/spikes.md" spike.py > spike.py
block run
run 'python3 days.py'
run 'python3 spike.py'
block longer
run 'python3 days.py 60'
run 'python3 spike.py | tail -3'
